#!/bin/sh
# Generated by FWShift: a Google Cloud network firewall policy, created with gcloud. Read the report first: what is
# not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE                              prints the commands; needs no access to Google Cloud
#   GCLOUD_OPTS='--project my-project' sh THIS_FILE     creates the policy and its rules
#
# The policy is associated with no network: nothing changes for any traffic until you associate it:
#   gcloud compute network-firewall-policies associations create --firewall-policy fwshift --network NETWORK --global-firewall-policy
# It decides every connection of that network. Set the network's enforcement order to BEFORE_CLASSIC_FIREWALL, or
# the VPC firewall rules of the network decide first. A policy of the same name stops the script before anything is
# created; a command gcloud refuses stops it where it is (delete the policy and run it again).
set -u
DRY_RUN="${DRY_RUN:-}"
GCLOUD_OPTS="${GCLOUD_OPTS:-}"
POLICY=fwshift
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
run() {
  if [ -n "$DRY_RUN" ]; then printf 'gcloud' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; return 0; fi
  gcloud "$@" $GCLOUD_OPTS --quiet >/dev/null || fail "gcloud $1 $2 $3 $4"
}
if [ -z "$DRY_RUN" ] && gcloud compute network-firewall-policies describe "$POLICY" --global $GCLOUD_OPTS >/dev/null 2>&1; then
  fail "a network firewall policy named $POLICY exists already; nothing was created"
fi

run compute network-firewall-policies create "$POLICY" --global '--description=Generated by FWShift; review the conversion report before associating it'

run compute network-firewall-policies rules create 1000 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=192.168.10.0/24 --dest-ip-ranges=203.0.113.0/29 --layer4-configs=tcp:21,tcp:80,tcp:443,udp:53 --enable-logging --description=rule-1
run compute network-firewall-policies rules create 1010 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=192.168.10.0/24 --dest-ip-ranges=203.0.113.0/29 --layer4-configs=tcp:21,tcp:80,tcp:443,udp:53 --enable-logging --description=rule-1
run compute network-firewall-policies rules create 1020 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=172.16.20.10/32,203.0.113.2/32 --layer4-configs=tcp:443 --description=rule-18
run compute network-firewall-policies rules create 1030 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=172.16.20.10/32,203.0.113.2/32 --layer4-configs=tcp:443 --description=rule-18
run compute network-firewall-policies rules create 1040 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=203.0.113.0/29 --dest-ip-ranges=172.16.20.10/32 --layer4-configs=tcp:443 --enable-logging --description=rule-2
run compute network-firewall-policies rules create 1050 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=203.0.113.0/29 --dest-ip-ranges=172.16.20.10/32 --layer4-configs=tcp:443 --enable-logging --description=rule-2
run compute network-firewall-policies rules create 1060 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=203.0.113.0/29 --dest-ip-ranges=172.16.20.25/32 --layer4-configs=tcp:25 --description=rule-6
run compute network-firewall-policies rules create 1070 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=203.0.113.0/29 --dest-ip-ranges=172.16.20.25/32 --layer4-configs=tcp:25 --description=rule-6
run compute network-firewall-policies rules create 1080 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=192.168.10.50/32 --dest-ip-ranges=172.16.20.10/32,172.16.20.25/32 --layer4-configs=tcp:22 --enable-logging --description=rule-7
run compute network-firewall-policies rules create 1090 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=192.168.10.50/32 --dest-ip-ranges=172.16.20.10/32,172.16.20.25/32 --layer4-configs=tcp:22 --enable-logging --description=rule-7
run compute network-firewall-policies rules create 1100 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=172.16.20.0/24 --dest-ip-ranges=203.0.113.0/29 --layer4-configs=all --description=rule-8
run compute network-firewall-policies rules create 1110 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=172.16.20.0/24 --dest-ip-ranges=203.0.113.0/29 --layer4-configs=all --description=rule-8
run compute network-firewall-policies rules create 1120 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=192.168.10.0/24 --dest-ip-ranges=172.16.20.0/24 --layer4-configs=tcp:8000-8010 --description=rule-12
run compute network-firewall-policies rules create 1130 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=192.168.10.0/24 --dest-ip-ranges=172.16.20.0/24 --layer4-configs=tcp:8000-8010 --description=rule-12
run compute network-firewall-policies rules create 1140 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=192.168.10.200/29,192.168.10.208/29,192.168.10.216/30,192.168.10.220/32 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --description=rule-3
run compute network-firewall-policies rules create 1150 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=192.168.10.200/29,192.168.10.208/29,192.168.10.216/30,192.168.10.220/32 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --description=rule-3
run compute network-firewall-policies rules create 1160 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=192.168.10.0/24 --dest-ip-ranges=172.16.20.25/32 --layer4-configs=tcp:25 --description=rule-17
run compute network-firewall-policies rules create 1170 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=192.168.10.0/24 --dest-ip-ranges=172.16.20.25/32 --layer4-configs=tcp:25 --description=rule-17
run compute network-firewall-policies rules create 1180 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --description=fwshift-default-deny
run compute network-firewall-policies rules create 1190 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --description=fwshift-default-deny
run compute network-firewall-policies rules create 1200 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=all --description=fwshift-default-deny
run compute network-firewall-policies rules create 1210 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=all --description=fwshift-default-deny

# Not written:
#   rule-10: the source of the rule is in zone vpn-ipsec, and a rule of Google Cloud names no zone: give the networks behind vpn-ipsec with --zone-network
#   rule-11: host name object update-host: the rules are written with addresses
#   rule-13: what it allows cannot be said by a rule of Google Cloud
#   rule-14: not converted: NETMAP on the rule: which addresses its packet filter rule names is not documented; the destination of the rule is in zone vpn-ipsec, and a rule of Google Cloud names no zone: give the networks behind vpn-ipsec with --zone-network
#   rule-7-2: the source of the rule is in zone vpn-ipsec, and a rule of Google Cloud names no zone: give the networks behind vpn-ipsec with --zone-network
#   rule-16: not converted: flag 'MIRROR' is not one FWShift reads
#   rule-9: references 'blocked-region': address 'geoip:XX' is not a form FWShift reads; the destination 'blocked-region' holds members only its platform knows; a rule of Google Cloud names addresses

echo 'Done. Associate the policy with the network when you are ready; until then nothing changes.' >&2
